reference.cpp:
#include <cstdio>
#include <vector>
#include <string>
#include <queue>
#include <sstream>
#include <iostream>

struct Node {
    long long v;
    Node *l = nullptr, *r = nullptr;
};

Node* buildTree(const std::vector<std::string> &t) {
    if (t.empty() || t[0] == "null") return nullptr;
    Node *root = new Node{std::stoll(t[0])};
    std::queue<Node*> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < t.size()) {
        Node *cur = q.front(); q.pop();
        if (i < t.size()) {
            if (t[i] != "null") { cur->l = new Node{std::stoll(t[i])}; q.push(cur->l); }
            ++i;
        }
        if (i < t.size()) {
            if (t[i] != "null") { cur->r = new Node{std::stoll(t[i])}; q.push(cur->r); }
            ++i;
        }
    }
    return root;
}

int k, cnt = 0;
long long ans = 0;

void inorder(Node *n) {
    if (!n || cnt >= k) return;
    inorder(n->l);
    if (++cnt == k) { ans = n->v; return; }
    inorder(n->r);
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    scanf("%d", &k);

    std::istringstream iss(line);
    std::vector<std::string> tok;
    std::string t;
    while (iss >> t) tok.push_back(t);

    inorder(buildTree(tok));
    printf("%lld\n", ans);
    return 0;
}
